-- Generated by scripts/build-parts-seed.ps1 from the catalog CSV. Safe to re-run (upsert on sku).
on conflict (sku) do update set
  sku_8digit = excluded.sku_8digit, page = excluded.page, name_en = excluded.name_en, name_es = excluded.name_es,
  module = excluded.module, subassembly = excluded.subassembly, price_cad = excluded.price_cad,
  qty_per_machine = excluded.qty_per_machine, on_hand = excluded.on_hand, notes = excluded.notes;
